    const bar=$('progress',card);bar.value=progress;bar.dataset.estimateAvailable=finite(e.progress)?'true':'false';bar.setAttribute('aria-valuetext',finite(e.progress)?`${Math.round(progress*100)}%`:'진행률 추정 대기');
