  const monitor=`<fieldset ${child?'disabled':''} class="execution-fields"><legend>계산 모니터링</legend><label class="check-label"><input type="checkbox" data-field="monitoring_cpu" ${v.monitoring_cpu?'checked':''}>모니터링 별도 코어 배치</label>${v.monitoring_cpu?`<div class="field"><label for="monitoring-command">모니터링 스크립트</label><input id="monitoring-command" data-field="monitoring_command" value="${attr(v.monitoring_command||'./Allmonitor')}"><small>계산 CPU와 겹치지 않는 물리 CPU 1개에서 실행합니다. 기본값: ./Allmonitor</small></div>`:''}</fieldset>`;
  const queue=child?'':`<fieldset class="execution-fields"><legend>이름 있는 대기열</legend>${inputField('queue_id','대기열 이름','macro1','개수 제한 없음 · 매크로는 전용 이름을 사용합니다. quota는 실행할 케이스의 코어 수로 자동 결정됩니다.')}${macro?`<label class="check-label"><input type="checkbox" data-field="dynamic_cores" ${v.dynamic_cores?'checked':''}>동적 코어 매크로 · 실행할 하위 케이스의 NP만큼 quota 자동 확보</label>`:''}</fieldset>`;
  if(!explicit&&!child)return source+queue+monitor;
  return source+queue+`<div class="notice">일반 작업은 지정한 코어 수가 quota입니다. 동적 매크로는 실행할 하위 케이스의 코어 수만큼 가용 CPU를 확보하며, 부족하면 필요한 대기열의 현재 작업 종료를 기다립니다.</div><fieldset ${child?'disabled':''} class="execution-fields">${inputField('macro_cores','병렬 CPU 개수','예: 48',macro?(v.dynamic_cores?'새 하위 케이스의 기본값입니다.':'모든 하위 케이스에 공통 적용하며 이 값이 quota입니다.'):'이 티켓의 실행 quota입니다.',false,'number')}${inputField('macro_command','실행 명령','./Allrun','보통 ./Allrun을 사용합니다.')}<details><summary>고급 CPU 설정</summary><p class="foot-note">자동 배정을 권장합니다. 수동 설정은 기존 티켓 호환을 위해 제공합니다.</p><div class="field"><label for="cpu-policy">CPU 배정 방식</label><select id="cpu-policy" data-field="macro_cpu_policy"><option value="auto" ${v.macro_cpu_policy==='auto'?'selected':''}>자동 배정 (권장)</option><option value="manual" ${v.macro_cpu_policy==='manual'?'selected':''}>수동 배정</option></select></div>${v.macro_cpu_policy==='manual'?inputField('macro_cpu_set','CPU 범위','0-23,26-49')+`<label class="check-label"><input type="checkbox" data-field="macro_cross_socket" ${v.macro_cross_socket?'checked':''}>소켓 간 실행 허용</label>`:''}</details></fieldset>`+monitor;
