  if(S.tab==='rules')form=`<div class="notice">정상 종료는 controlDict의 종료 조건과 최신 로그의 최종 Time으로 판단합니다.</div><label class="field-label" for="preset">실패 패턴 템플릿</label><div class="preset-row"><select id="preset">${Object.keys(S.patterns).map(CFDLog.wrap((name=>`<option>${esc(name)}</option>`),"web.ui.callback:L131:C234")).join('')}</select>${btn('apply-preset','적용')}${btn('save-preset','템플릿 저장')}</div>${textareaField('failure_patterns','실패 로그 패턴','정규식 하나를 한 줄씩 입력하세요. 비워 두어도 기본 OpenFOAM 오류 감지는 사용할 수 있습니다.')}<div class="field"><label class="check-label"><input type="checkbox" data-field="openfoam_defaults" ${v.openfoam_defaults?'checked':''}>기본 OpenFOAM 오류 패턴 포함</label></div>${textareaField('updated_files','갱신 여부를 확인할 파일','케이스 기준 상대 경로를 한 줄에 하나씩 입력하세요.')}`;
  if(S.tab==='exports')form=`<div class="notice">요청 시 확인하거나 다운로드할 데이터를 정의합니다. 매크로에서는 모든 하위 케이스에 같은 상대 경로를 적용합니다.</div><div id="export-rows">${exportRows()}</div>${btn('add-export','＋ 요청 데이터 추가')}`;
